Task: Put the red cube into the red tray and the blue cube into the blue tray.

Skill code (numbered):
  1| import math
  2| 
  3| def run(robot):
  4|     """Sort cubes by colour into matching trays."""
  5|     robot.home()
  6| 
  7|     # Get current scene description
  8|     obs = robot.observe()
  9| 
 10|     # Separate cubes and trays
 11|     cubes = {name: obj for name, obj in obs['objects'].items() if obj['shape'] == 'cube'}
 12|     trays = {name: fix for name, fix in obs['fixtures'].items() if fix['kind'] == 'tray'}
 13| 
 14|     # Map colour -> tray name (e.g., 'red' -> 'red_tray')
 15|     colour_to_tray = {}
 16|     for name, fix in trays.items():
 17|         colour_to_tray[fix['color']] = name
 18| 
 19|     overall_success = True
 20| 
 21|     for cube_name, cube in cubes.items():
 22|         colour = cube['color']
 23|         tray_name = colour_to_tray.get(colour)
 24|         if tray_name is None:
 25|             robot.log(f"No tray found for colour '{colour}'")
 26|             overall_success = False
 27|             continue
 28| 
 29|         # Get up-to-date poses (perception is noisy)
 30|         cube_pose = robot.get_pose(cube_name)
 31|         tray_pose = robot.get_pose(tray_name)
 32| 
 33|         if not _pick_and_place(robot, cube_pose, tray_pose):
 34|             robot.log(f"Failed to place {cube_name} into {tray_name}")
 35|             overall_success = False
 36| 
 37|     return overall_success
 38| 
 39| 
 40| def _pick_and_place(robot, cube_pose, tray_pose):
 41|     """Attempt one pick‑and‑place cycle. Returns True on success."""
 42|     max_attempts = 2
 43|     lift_height = 0.10          # safe travel height above the table
 44|     grasp_offset = 0.05         # how far above the cube centre we close the fingers
 45|     place_offset = -0.005       # how far below the tray top we release (negative = inside)
 46| 
 47|     for attempt in range(max_attempts):
 48|         try:
 49|             # 1. Move above the cube
 50|             above_cube = [cube_pose['pos'][0], cube_pose['pos'][1], lift_height]
 51|             robot.move_to(*above_cube, speed=0.2)
 52| 
 53|             # 2. Descend to a grasp height (just above the cube centre)
 54|             # Ensure we are not too low to avoid table collisions
 55|             grasp_z = max(cube_pose['pos'][2] + grasp_offset,
 56|                           cube_pose['pos'][2] + 0.05)
 57|             robot.move_to(cube_pose['pos'][0], cube_pose['pos'][1], grasp_z,
 58|                           speed=0.05)
 59| 
 60|             # 3. Close fingers
 61|             if not robot.grasp():
 62|                 robot.release()  # ensure hand is open before retrying
 63|                 continue
 64| 
 65|             # 4. Verify we actually hold something
 66|             if robot.holding() is None:
 67|                 robot.release()
 68|                 continue
 69| 
 70|             # 5. Lift the cube
 71|             robot.move_to(cube_pose['pos'][0], cube_pose['pos'][1], lift_height,
 72|                           speed=0.05)
 73| 
 74|             # 6. Move above the target tray (use fresh tray pose to account for any drift)
 75|             tray_pose = robot.get_pose(tray_name)  # refresh perception
 76|             above_tray = [tray_pose['pos'][0], tray_pose['pos'][1], lift_height]
 77|             robot.move_to(*above_tray, speed=0.2)
 78| 
 79|             # 7. Lower to just inside the tray top
 80|             place_z = tray_pose['pos'][2] + place_offset
 81|             robot.move_to(tray_pose['pos'][0], tray_pose['pos'][1], place_z,
 82|                           speed=0.05)
 83| 
 84|             # 8. Release the cube
 85|             robot.release()
 86|             robot.wait(0.05)  # brief pause to let the object settle
 87| 
 88|             # 9. Retract to safe height
 89|             robot.move_to(tray_pose['pos'][0], tray_pose['pos'][1], lift_height,
 90|                           speed=0.05)
 91| 
 92|             return True  # success for this cube
 93| 
 94|         except Exception as e:  # catches MotionError and other unexpected issues
 95|             robot.log(f"Attempt {attempt+1} failed: {e}")
 96|             robot.release()  # try to leave the hand open
 97|             continue
 98| 
 99|     # If we exit the loop, all attempts failed
100|     return False

